#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
unsigned int count = 0;
int lastRaw = HIGH;
int stableState = HIGH;
unsigned long changedAt = 0;

void setup() {
  pinMode(2, INPUT_PULLUP);
  display.setBrightness(7);
  display.showNumberDec(count, false);
  lastRaw = digitalRead(2);
  changedAt = millis();
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableState && now - changedAt >= 30) {
    stableState = raw;
    if (stableState == LOW) {
      count = (count + 1) % 10000;
      display.showNumberDec(count, false);
    }
  }
}
